exercise.solution:
use std::rc::Rc;

fn share(a: &Rc<String>) -> Rc<String> {
    Rc::clone(a)
}

fn main() {
    let a = Rc::new(String::from("hello"));
    let b = share(&a);
    println!("count = {}", Rc::strong_count(&a));
    println!("{a} {b}");
}
